--- Determine known status for knowledge-checkable item types.
-- - Recipes: IsItemLinkRecipeKnown
-- - Collectible grants (monster trophies, rare fish): IsCollectibleUnlocked
-- - Motifs (books/chapters): IsItemLinkBookKnown (per-character style knowledge)
-- - Scribing scripts: IsCraftedAbilityScriptUnlocked (per-character script knowledge)
-- - Collectible fragments: IsCollectibleOwnedByDefId (account-wide, via container collectible ID)
-- Returns undefined for items without a knowledge API.
function ____exports.isItemKnown(itemLink, itemType)
    if itemType == ITEMTYPE_RECIPE then
        return IsItemLinkRecipeKnown(itemLink)
    end
    local useType = GetItemLinkItemUseType(itemLink)
    if useType == ITEM_USE_TYPE_COLLECTIBLE_GRANT then
        local collectibleId = GetItemLinkItemUseReferenceId(itemLink)
        return IsCollectibleUnlocked(collectibleId)
    end
    if useType == ITEM_USE_TYPE_CRAFTED_ABILITY_SCRIPT then
        return IsCraftedAbilityScriptUnlocked(GetItemLinkItemUseReferenceId(itemLink))
    end
    local ____, specializedType = GetItemLinkItemType(itemLink)
    if specializedType == SPECIALIZED_ITEMTYPE_RACIAL_STYLE_MOTIF_BOOK or specializedType == SPECIALIZED_ITEMTYPE_RACIAL_STYLE_MOTIF_CHAPTER then
        return IsItemLinkBookKnown(itemLink)
    end
    if specializedType == SPECIALIZED_ITEMTYPE_TROPHY_COLLECTIBLE_FRAGMENT or specializedType == SPECIALIZED_ITEMTYPE_TROPHY_RUNEBOX_FRAGMENT then
        local grantedCollectibleId = GetItemLinkContainerCollectibleId(itemLink)
        if grantedCollectibleId == 0 then
            return nil
        end
        return IsCollectibleOwnedByDefId(grantedCollectibleId)
    end
    if specializedType == SPECIALIZED_ITEMTYPE_COLLECTIBLE_STYLE_PAGE then
        local grantedCollectibleId = GetItemLinkContainerCollectibleId(itemLink)
        if grantedCollectibleId == 0 then
            return nil
        end
        return IsCollectibleUnlocked(grantedCollectibleId)
    end
    return nil
end
