    return specializedType == SPECIALIZED_ITEMTYPE_RACIAL_STYLE_MOTIF_BOOK or specializedType == SPECIALIZED_ITEMTYPE_RACIAL_STYLE_MOTIF_CHAPTER or specializedType == SPECIALIZED_ITEMTYPE_TROPHY_COLLECTIBLE_FRAGMENT or specializedType == SPECIALIZED_ITEMTYPE_TROPHY_RUNEBOX_FRAGMENT or specializedType == SPECIALIZED_ITEMTYPE_COLLECTIBLE_STYLE_PAGE
end
