            return {currentRank = currentRank, maxRank = maxRank}
        end
        local syncedRank = readSyncedRank(characters, charId, esoSkillLineId)
        if syncedRank == nil then
            return nil
        end
        return {currentRank = syncedRank, maxRank = maxRank}
    end
end
return ____exports
 end,
