    local hasValidFurnishingFilterType = #subfilterTypes >= 3
    if category == "Weapons" then
        if invalidFilterType and not isCompanionItem and isWeaponRow(row) then
            return true
        end
        if hasSingleFilterMatch then
            do
                local i = 0
                while i < #subfilterTypes do
                    if row.weaponType == subfilterTypes[i + 1] and not isCompanionItem then
                        return true
                    end
                    i = i + 1
                end
            end
        end
        return false
    end
    if category == "Armor" then
        if invalidFilterType and not isCompanionItem then
            local hasShield = row.weaponType == WEAPONTYPE_SHIELD
            local hasDisguise = row.specializedItemType == SPECIALIZED_ITEMTYPE_DISGUISE
            local hasCostume = row.specializedItemType == SPECIALIZED_ITEMTYPE_COSTUME
            if hasShield or hasDisguise or isWearableRow(row) or hasCostume then
                return true
            end
        end
        if hasDualFilterMatch and row.armorType == subfilterTypes[1] then
            do
                local i = 1
                while i < #subfilterTypes do
                    if row.equipType == subfilterTypes[i + 1] and not isCompanionItem then
                        return true
                    end
                    i = i + 1
                end
            end
        end
        return false
    end
    if category == "Jewelry" then
        if invalidFilterType and not isCompanionItem and isJewelryRow(row) then
            return true
        end
        if hasSingleFilterMatch then
            do
                local i = 0
                while i < #subfilterTypes do
                    if row.equipType == subfilterTypes[i + 1] and not isCompanionItem then
                        return true
                    end
                    i = i + 1
                end
            end
        end
        return false
    end
    if category == "Companion" then
        if not isCompanionItem then
            return false
        end
        if invalidFilterType then
            return true
        end
        if hasDualFilterMatch then
            if subfilterTypes[1] == ITEMTYPE_ARMOR then
                do
                    local i = 1
                    while i < #subfilterTypes do
                        if row.equipType == subfilterTypes[i + 1] then
                            return true
                        end
                        i = i + 1
                    end
                end
            elseif subfilterTypes[1] == ITEMTYPE_WEAPON then
                do
                    local i = 1
                    while i < #subfilterTypes do
                        if row.weaponType == subfilterTypes[i + 1] then
                            return true
                        end
                        i = i + 1
                    end
                end
            end
        end
        return false
    end
    if category == "Furnishing" then
        if invalidFilterType and row.isFurnishing then
            return true
        end
        if hasValidFurnishingFilterType and row.itemType == subfilterTypes[1] and row.furnitureCategoryId == subfilterTypes[2] then
            do
                local i = 2
                while i < #subfilterTypes do
                    if row.furnitureSubcategoryId == subfilterTypes[i + 1] then
                        return true
                    end
                    i = i + 1
                end
            end
        end
        return false
    end
    if category == "Consumable" or category == "Materials" or category == "Misc" then
        if hasSingleFilterMatch then
            do
                local i = 0
                while i < #subfilterTypes do
                    if row.itemType == subfilterTypes[i + 1] then
                        return true
                    end
                    i = i + 1
                end
            end
        end
        return false
    end
    if category == "Appearance" or category == "MiscSubfilter" then
        if hasSingleFilterMatch then
            do
                local i = 0
                while i < #subfilterTypes do
                    if row.specializedItemType == subfilterTypes[i + 1] then
                        return true
                    end
                    i = i + 1
                end
            end
        end
        return false
    end
    if category == "Specialized" then
        if hasDualFilterMatch and row.itemType == subfilterTypes[1] then
            do
                local i = 1
                while i < #subfilterTypes do
                    if row.specializedItemType == subfilterTypes[i + 1] then
                        return true
                    end
                    i = i + 1
                end
            end
        end
        return false
    end
    if category == "Junk" then
        if hasSingleFilterMatch and row.itemType == subfilterTypes[1] then
            return true
        end
        return false
    end
    return false
end
return ____exports
 end,
