--- The seven body-armor equip slots shared by the Armor + Companion strips.
local function bodyEquipSlots()
    return {
        EQUIP_TYPE_HEAD,
        EQUIP_TYPE_SHOULDERS,
        EQUIP_TYPE_CHEST,
        EQUIP_TYPE_HAND,
        EQUIP_TYPE_LEGS,
        EQUIP_TYPE_FEET,
        EQUIP_TYPE_WAIST
    }
end
--- `{ armorType, ...bodyEquipSlots }` — the Armor strip's per-weight list.
local function armorWeight(armorType)
    local out = {armorType}
    local slots = bodyEquipSlots()
    do
        local i = 0
        while i < #slots do
            local slot = slots[i + 1]
            if slot ~= nil then
                out[#out + 1] = slot
            end
            i = i + 1
        end
    end
    return out
end
