["temper.inventory.addon.src.writ-crafting-iterations"] = function(...) 
local ____exports = {}
--- How many single-iteration crafts are needed to produce at least `needed`
-- items, given each iteration yields `yieldPerIter` and at most `maxIter`
-- iterations are possible (ingredient-bounded). Returns 0 when nothing can be
-- crafted (non-positive yield or zero iterations available).
function ____exports.computeCraftIterations(needed, yieldPerIter, maxIter)
    if needed <= 0 then
        return 0
    end
    if yieldPerIter < 1 then
        return 0
    end
    if maxIter < 1 then
        return 0
    end
    local itersNeeded = math.ceil(needed / yieldPerIter)
    return math.min(itersNeeded, maxIter)
end
return ____exports
