["temper.equipment.src.weapons.weapon-types-data"] = function(...) 
local ____lualib = require("lualib_bundle")
local Set = ____lualib.Set
local __TS__New = ____lualib.__TS__New
local ____exports = {}
local ____create_2Ddata_2Dfile = require("shared.utils.narrow.src.create-data-file")
local createDataFile = ____create_2Ddata_2Dfile.createDataFile
local ____level_2Dscaling = require("temper.equipment.src.level-scaling")
local getWeaponPowerForLevel = ____level_2Dscaling.getWeaponPowerForLevel
local ____temper_2Dweapon_2Dtype_2Egenerated = require("temper.equipment.src.weapons.generated.temper-weapon-type.generated")
local TEMPER_WEAPON_TYPES_BY_ID = ____temper_2Dweapon_2Dtype_2Egenerated.TEMPER_WEAPON_TYPES_BY_ID
____exports.weaponTypes = createDataFile()(TEMPER_WEAPON_TYPES_BY_ID)
--- Weapon power values by category and quality level.
-- Values fetched from UESP API (scripts/fetch-equipment-base-values.script.ts).
-- 
-- Categories:
-- - standard: 1335 legendary (all 1H melee, bow, all staves)
-- - twoHandedMelee: 1571 legendary (greatsword, battleaxe, maul only)
-- 
-- Note: Fine and Superior have identical values - this is how ESO works.
local WEAPON_POWER_QUALITY_VALUES = {standard = {
    normal = 1072,
    fine = 1108,
    superior = 1108,
    epic = 1132,
    legendary = 1335
}, twoHandedMelee = {
    normal = 1262,
    fine = 1304,
    superior = 1304,
    epic = 1332,
    legendary = 1571
}}
--- Two-handed melee weapons that use higher power values
local TWO_HANDED_MELEE_TYPES = __TS__New(Set, {"greatsword", "battleaxe", "maul"})
--- Get the weapon power value for a weapon type at a specific quality and level.
-- 
-- Most weapons use standard power (1335 legendary at CP160): all 1H melee, bow, all staves.
-- Only 2H melee weapons (greatsword, battleaxe, maul) use higher power (1571 legendary at CP160).
-- 
-- For CP160 (level undefined), uses the pre-computed lookup table.
-- For other levels, uses the level scaling formula.
-- 
-- @param weaponType - The weapon type ID
-- @param quality - The equipment quality (defaults to legendary)
-- @param level - The item level (undefined = CP160)
-- @returns The weapon power value for the given quality and level
-- @example getWeaponPower("greatsword", "legendary") // Returns 1571 (CP160)
-- getWeaponPower("sword", "epic") // Returns 1132 (CP160)
-- getWeaponPower("sword", "legendary", 1) // Returns ~327 (level 1)
function ____exports.getWeaponPower(weaponType, quality, level)
    if quality == nil then
        quality = "legendary"
    end
    if weaponType == "no-type" then
        return 0
    end
    local isTwoHandedMelee = TWO_HANDED_MELEE_TYPES:has(weaponType)
    if level ~= nil then
        return getWeaponPowerForLevel(level, isTwoHandedMelee, quality)
    end
    if isTwoHandedMelee then
        return WEAPON_POWER_QUALITY_VALUES.twoHandedMelee[quality]
    end
    return WEAPON_POWER_QUALITY_VALUES.standard[quality]
end
return ____exports
 end,
