            0,
            math.min(deficit, snap.withdrawableFromOpen)
        )
        return count > 0 and ({direction = "withdraw", count = count}) or NONE
    end
    local excess = snap.backpackCount - snap.selfTarget
    if excess > 0 then
        local allowed = excess
        if snap.openTierCap ~= nil then
            local capRemaining = math.max(0, snap.openTierCap - snap.openTierStorageCount)
            allowed = math.min(allowed, capRemaining)
        end
        local count = math.max(0, allowed)
        return count > 0 and ({direction = "deposit", count = count}) or NONE
    end
    return NONE
end
